tool.command:
mkdir -p run && cd run &&
cp '$d_file'   model.d &&
cp '$dat_file' model.dat &&
printf '%s\n' 'sim3de' '$output' '$nels $nxe $nze' '$aa $bb $cc' '$thx $thy $thz' '$emn $esd' '$varfnc' '0.3' > rfem.rf &&
rfemfield_thermal rfem model $instance_id 2>&1;
RC=\$?;
INST=model-${instance_id};
if [ -f "\${INST}.d" ] && [ -f "\${INST}.dat" ] && [ -f "\${INST}.mat" ]; then
    tar czf '$output_instance' "\${INST}.d" "\${INST}.dat" "\${INST}.mat";
else
    echo "rfemfield_thermal: missing output files (exit \${RC})" > '\${INST}.err';
    tar czf '$output_instance' --files-from /dev/null;
fi;
if [ -f rfem.res ]; then cp rfem.res '$output_res'; else echo "rfemfield_thermal: no .res" > '$output_res'; fi;
exit \${RC}
